#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node* prev;
};

void pushBack(Node** headRef, int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    newNode->next = nullptr;
    if (*headRef == nullptr) {
        newNode->prev = nullptr;
        *headRef = newNode;
        return;
    }
    Node* last = *headRef;
    while (last->next != nullptr) {
        last = last->next;
    }
    last->next = newNode;
    newNode->prev = last;
}

void deleteNode(Node** headRef, Node* target) {
    if (*headRef == nullptr || target == nullptr) {
        return;
    }
    if (*headRef == target) {
        *headRef = target->next;
    }
    if (target->next != nullptr) {
        target->next->prev = target->prev;
    }
    if (target->prev != nullptr) {
        target->prev->next = target->next;
    }
    delete target;
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->next;
    }
    cout << endl;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = nullptr;
    pushBack(&head, 10);
    pushBack(&head, 20);
    pushBack(&head, 30);
    Node* doomed = head->next;
    deleteNode(&head, doomed);
    deleteNode(&head, head);
    printList(head);
    freeList(head);
    return 0;
}
